      (1, 12445, 3, 'FC91DB04', '2095924552', null, '2026-03-01', '2026-03-04 08:42:47', '2026-03-01', 668, 668, 'PURIFICADOR', 1222, 1855.02, 7.7, 'V', 'HJU', null, null, 'HJU', '2026-03-04 00:00:00', 'V', null, null, null, 12, 5, 0, false, null, 0, null, null, null, null, null, 0, true, null, null, null, 3, 2026, null, 3, 0, 0, 0, null, null, null, null, 'C', true, 10, 2, null, null),
      (1, 12446, 3, 'D75900E0', '2127121148', null, '2026-02-16', '2026-03-04 09:52:34', '2026-02-16', 3596, 3596, 'HON PROF', 1027, 1160, 7.7, 'V', 'HJU', null, null, 'HJU', '2026-03-04 00:00:00', 'V', null, null, null, 12, 5, 0, false, null, 0, null, null, null, null, null, 0, true, null, null, null, 3, 2026, null, 2, 0, 0, 0, null, null, null, null, 'C', true, 10, 2, null, null),
      (1, 12447, 3, '29DA7EB1', '2703513', null, '2026-02-27', '2026-03-04 09:53:46', '2026-02-27', 276, 276, 'MTT Y REP', 1016, 1128.25, 7.7, 'V', 'HJU', null, null, 'HJU', '2026-03-04 00:00:00', 'V', null, null, null, 12, 5, 0, false, null, 0, null, null, null, null, null, 0, true, null, null, null, 3, 2026, null, 2, 0, 0, 0, null, null, null, null, 'C', true, 10, 4, null, null),
      (1, 12448, 3, 'F422C454', '23479110', null, '2026-02-19', '2026-03-04 09:55:07', '2026-02-19', 50, 50, 'QX - SEGURO BAM
PX. SILVIA RAFAELA LOPEZ ORTIZ
DR. ALEXIS OLIVA', 1009, 8045, 7.7, 'V', 'HJU', null, null, 'HJU', '2026-03-04 00:00:00', 'V', null, null, null, 12, 5, 0, false, null, 0, null, null, null, null, null, 0, true, null, null, null, 3, 2026, null, 2, 0, 0, 0, null, null, null, 'HJU', 'C', true, 10, 4, null, null),
      (1, 12449, 3, '3B7C1C21', '2009025998', null, '2026-02-24', '2026-03-04 10:15:40', '2026-02-24', 633, 633, 'QX - GRUPO PIT
